                    className={btnRetro({ tone: "primary" })}
                    onClick={() => {
                      posthog.capture('start_session_clicked', { source: 'landing_hero' });
                      navigate({ to: "/chat" });
                    }}
                  >
                    Initialize_Session →
                  </button>
                  <a className={btnRetro()} href="#install">
                    Build_From_Source
                  </a>
                </div>
              </div>

              <div className="hero-stage">
                <HeroTerminal />
              </div>
            </div>
          </div>
